     * A claim's amount at the rate the grade has in force on the claim's date, raised to the sheet's
     * floor when below it (a correction has no floor); null when it has no rate.
     */
    public BigDecimal live(Claim claim, String grade) {
        BigDecimal floor = claim.isCorrection() ? null : sheets.findById(claim.getSheetId()).map(Sheet::getFloor).orElse(null);
        return rates.findInForce(claim.getSheetId(), grade, claim.getDate())
                .map(rate -> due(claim.getAmount(), rate))
                .map(due -> floor != null && due.compareTo(floor) < 0 ? floor : due)
                .orElse(null);
    }

    /** What is due on an amount at a rate: the amount times the percent over 100, rounded half to even. */
    private static BigDecimal due(BigDecimal amount, Rate rate) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }
}
-- The sheet's terms: the number of days after its date a claim is due by. An OPEN claim whose
-- due-by is before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every
-- full 30 days it is overdue. Never bound by a statement; frozen in when the claim is settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
-- A person's grade is dated: the grade on the person row is the first they were given, applying from
-- the beginning of time; each later grade is recorded here from its date, one per date, and holds
-- from that date until the next.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
-- A correction: a claim with a negative amount, naming by number a SETTLED claim of the same person
-- that it corrects. Null on any other claim. The amount may now be below 0.00, but only on a
-- correction.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A new sheet starts on the real date; it is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- The sheet's floor: a claim's live due is at least it. Settled, stated and closed figures keep
-- what they were fixed at.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
-- A correction: a claim with a negative amount, naming by number a SETTLED claim of the same person
-- that it corrects. Null on any other claim. The amount may now be below 0.00, but only on a
-- correction.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_correction CHECK (amount >= 0 OR corrects IS NOT NULL);

