import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FLOOR, LATE_PCT, LIMIT, ROLES, TERMS, RoleName, RoleView, SettingsApi } from '../../core/settings';
import { Session } from '../../core/session';

// The sheet's settings (the clerk limit, the floor, the terms and the late percent) and the roles user names have on it (clerk by default,
// or steward), each changed through its own form.
@Component({
  selector: 'app-settings',
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <form (submit)="saveSettings($event)" aria-label="Change settings">
        <label for="setting-clerk-limit">Clerk limit (empty: no limit)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitEdited = true; settingsError.set(null)"
        />
        <label for="setting-floor">Floor</label>
        <input
          id="setting-floor"
          data-testid="setting-floor"
          inputmode="decimal"
          [value]="floorInput()"
